--
-- Table structure for table `drug_subscription`
--

DROP TABLE IF EXISTS `drug_subscription`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `drug_subscription` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '订阅ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `drug_id` int NOT NULL COMMENT '药品ID',
  `quantity` int DEFAULT '1' COMMENT '订阅数量',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态(0:取消;1:有效)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '订阅时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_drug` (`user_id`,`drug_id`) USING BTREE,
  KEY `idx_drug_id` (`drug_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

