/*!40000 ALTER TABLE `news` DISABLE KEYS */;
INSERT INTO `news` VALUES (1,'成年男性平均身高接近170，女性158','<p>中国人长高了！</p><p>成年男性平均身高接近170，女性158</p><p>报告显示，中国居民体格发育与营养不足问题持续改善，城乡差异逐步缩小。</p><p>中国成人平均身高继续增长，18-44岁男性和女性的平均身高分别为169.7厘米和158.0厘米。</p>',2,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/f0890964.jpg',NULL,0,0,'2024-07-11 15:40:04'),(2,'疾病，就像一位潜藏在暗处的狡猾猎手','<p>健康问题越来越引起重视。</p><p><strong>中国人的健康数据，触目惊心！</strong></p><p>高血压：1.6-1.7亿人</p><p>高血脂：1亿多人</p><p>糖尿病患者：1240万人</p><p>超重或者肥胖症：7000万-2亿人</p><p>这些冰冷的数字背后，是无数家庭的痛苦和无奈。</p>',4,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/50c810f4.jpg',NULL,1,1,'2024-07-12 10:00:00'),(3,'身体健康的十项指标，你知道几个？','<p>健康的准确定义应该是身体健康，心理健康，具有良好的社会适应性。</p><h4>1.饮食指标</h4><p>成人每天应该吃500克左右的食物。</p><h4>2.体重指标</h4><p>体重并不是越轻越好。</p><h4>3.体温指标</h4><p>正常人的体温应该在36℃～37℃。</p>',3,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/6b87fee8.jpg',NULL,0,0,'2024-07-13 14:30:00'),(4,'健康5大准则，做到2个就很厉害','<p>打败一个年轻人，只需要一张体检报告单。</p><p>不少疾病都在呈现年轻化的趋势。</p><p>骨质疏松、中风、二型糖尿病等等。</p><p>疾病不是源于人身体结构上的不足或缺陷，而是源于生活方式带来的自我损伤。</p>',5,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/a6c7d3e1.jpg',NULL,1,1,'2024-07-14 09:00:00'),(5,'10条身体健康的\"金标准\"','<p>一个人的身体是否健康，各项身体常见指标指数是最直接的判断。</p><p><strong>血压标准：</strong>收缩压＜120mmHg，舒张压＜80mmHg</p><p><strong>血糖标准：</strong>空腹血糖3.9-6.1mmol/L</p><p><strong>血脂标准：</strong>总胆固醇＜5.2mmol/L</p>',3,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/9edc2e89.jpg',NULL,0,0,'2024-07-14 14:34:58'),(6,'睡眠质量对健康的影响','<p>睡眠是人体恢复的重要过程。</p><p>成年人每天需要7-8小时睡眠。</p><p>良好的睡眠可以：</p><p>1. 增强免疫力</p><p>2. 改善记忆力</p><p>3. 促进新陈代谢</p>',5,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/a6fe88e2.jpg',NULL,0,0,'2024-07-15 16:00:00'),(7,'快节奏的现代生活与健康','<p>快节奏的现代生活，如同一只无形的手，推动着我们不断前行。</p><p>作息不规律、高油高盐的饮食等，悄然侵蚀着我们的健康。</p><p>我们需要的，不仅仅是医疗技术的日新月异，更需要的是健康理念的深入人心。</p>',1,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/b2c347010.jpg',NULL,0,0,'2024-07-16 11:00:00'),(8,'我们对健康的重视程度仍然远远不够','<p>在过去，随着中国经济的高速发展，许多人的生活水平和物质条件得到了很大的改善。</p><p>然而，这种快速发展的背后，却隐藏着一些被忽视的问题，其中较为突出的就是健康问题。</p><p>健康对于每个人来说都是刻不容缓的。</p>',2,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/c4cbe3b4.jpg',NULL,0,0,'2024-07-17 09:30:00'),(9,'慢性疾病的预防与管理','<p>慢性疾病是现代社会的主要健康威胁。</p><p>常见慢性病包括：</p><p>1. 高血压</p><p>2. 糖尿病</p><p>3. 心脏病</p><p>预防措施：健康饮食、适量运动、定期体检</p>',4,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/ed9c50f10.jpg',NULL,0,0,'2024-07-18 14:00:00'),(10,'如何建立健康的生活方式','<p>建立健康的生活方式需要：</p><p>1. 均衡饮食</p><p>2. 规律运动</p><p>3. 充足睡眠</p><p>4. 良好心态</p><p>5. 定期体检</p><p>从现在开始，为健康投资！</p>',1,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/361b9a73.png',NULL,1,1,'2024-07-19 10:00:00'),(11,'保健养生从现在做起','<p>为了家人，为了亲朋，保健养生从现在做起！</p><p>养生小贴士：</p><p>1. 多喝水</p><p>2. 少熬夜</p><p>3. 多运动</p><p>4. 保持好心情</p>',5,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/e7bcce46.png',NULL,0,0,'2024-07-20 15:00:00'),(12,'健康饮食的重要性','<p>健康饮食是身体健康的基础。</p><p>建议：</p><p>1. 多吃蔬菜水果</p><p>2. 控制盐糖摄入</p><p>3. 适量蛋白质</p><p>4. 少吃加工食品</p><p>5. 规律饮食时间</p>',1,'http://localhost:21090/api/personal-health/v1.0/file/getFile?fileName=articles/ba3b54812.png',NULL,0,0,'2024-07-21 11:00:00'),(13,'慢性阻塞性肺疾病(COPD)诊疗规范','<h1><strong>一、定义与分型</strong></h1><p>COPD是一种以持续性气流受限为特征的常见、可预防和可治疗的慢性呼吸系统疾病。典型表型包括：慢性支气管炎型（咳嗽咳痰为主）和肺气肿型（呼吸困难为主）。</p><h1><strong>二、诊断标准</strong></h1><p>1. 危险因素：吸烟史（吸烟指数=包/天×年数&gt;10包年）、生物燃料暴露、职业粉尘等</p><p>2. 临床症状：慢性咳嗽/咳痰+进行性呼吸困难（mMRC分级评估）</p><p>3. 肺功能：支气管扩张剂吸入后FEV1/FVC &lt; 0.70（不可逆气流受限）</p><h1><strong>三、气流受限严重度分级（GOLD分期）</strong></h1><table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">GOLD分级</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">FEV1(%预计值)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">严重度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">典型表现</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">GOLD 1</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">≥80%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">轻度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">可能无症状</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">GOLD 2</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">50-79%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">中度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">劳力后气短</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">GOLD 3</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">30-49%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">重度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">日常活动即气短</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">GOLD 4</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">&lt;30%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">极重度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"288\">静息时亦气短，常伴呼吸衰竭</td></tr></tbody></table><h1><strong>四、GOLD ABCD综合评估（症状+急性加重风险）</strong></h1><table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">分组</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">特征</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">初始治疗</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">A组</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">mMRC 0-1/CAT&lt;10 急性加重≤1次(无住院)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">短效支气管扩张剂 prn</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">B组</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">mMRC≥2/CAT≥10 急性加重≤1次(无住院)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">LAMA 或 LABA 单药</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">C组</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">mMRC 0-1/CAT&lt;10 急性加重≥2次或≥1次住院</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">LAMA 单药</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">D组</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">mMRC≥2/CAT≥10 急性加重≥2次或≥1次住院</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">LAMA+LABA；若血EOS≥300→ICS+LABA+LAMA</td></tr></tbody></table><h1><strong>五、药物治疗</strong></h1><h2><strong>1. 支气管扩张剂（核心治疗）</strong></h2><p>SABA（短效β2激动剂）：沙丁胺醇，按需使用，作用维持4-6小时</p><p>SAMA（短效抗胆碱能）：异丙托溴铵，按需使用</p><p>LABA（长效β2激动剂）：福莫特罗、沙美特罗、茚达特罗，作用维持12-24小时，qd/bid</p><p>LAMA（长效抗胆碱能）：噻托溴铵、乌美溴铵，作用维持24小时，qd</p><h2><strong>2. 吸入性糖皮质激素(ICS)</strong></h2><p>血嗜酸性粒细胞(EOS)≥300个/μL → ICS联合治疗获益最大</p><p>EOS 100-299个/μL → ICS联合治疗有一定获益</p><p>EOS&lt;100个/μL → ICS获益小，不推荐常规使用</p><p>常见不良反应：口腔念珠菌感染（每次吸入后漱口）、声音嘶哑</p><h1><strong>六、非药物治疗</strong></h1><p>1. 戒烟：唯一被证实可延缓FEV1下降速度的干预措施</p><p>2. 肺康复：运动训练+营养指导+疾病自我管理教育，疗程6-12周</p><p>3. 长期氧疗(LTOT)：静息PaO2≤55mmHg或SaO2≤88%，每天吸氧≥15小时</p><p>4. 无创正压通气(NPPV)：稳定期高碳酸血症(PaCO2≥52mmHg)</p><p>5. 外科手术：肺减容术(特定肺气肿患者)、肺移植(终末期)</p><h1><strong>七、急性加重期管理</strong></h1><p>诱因：呼吸道感染（病毒&gt;细菌）、空气污染、治疗中断</p><p>诊断依据：呼吸困难加重+痰量增多+痰变脓性（满足≥2项为中度，全部满足为重度）</p><h2><strong>分级治疗</strong></h2><p>轻度加重：增加SABA/SAMA使用频率</p><p>中度加重：口服泼尼松30-40mg/天×5-7天 + 抗生素（满足痰变脓性条件时）</p><p>重度加重（需住院）：雾化吸入支气管扩张剂 + 全身糖皮质激素 + 必要时无创通气或气管插管</p><h2><strong>抗生素使用指征</strong></h2><p>呼吸困难加重+痰量增多+痰变脓性 → 三联征全满足或只有后面两项</p><p>首选：阿莫西林/克拉维酸、头孢呋辛、呼吸喹诺酮（莫西沙星/左氧氟沙星）</p><p>有铜绿假单胞菌感染风险者：环丙沙星或抗假单胞β内酰胺类</p><h1><strong>八、合并症筛查与管理</strong></h1><p>COPD常见肺外合并症：</p><p>1. 心血管疾病（COPD死亡首要原因之一）：缺血性心脏病、心衰、房颤</p><p>2. 骨质疏松：糖皮质激素使用+吸烟+营养不良+低体重</p><p>3. 焦虑抑郁：约40%COPD患者合并，影响治疗依从性和生活质量</p><p>4. 胃食管反流：加重咳嗽症状，PPI试验性治疗</p><p>5. 肺癌：COPD是肺癌独立危险因素，推荐LDCT筛查</p><p><br></p><p>声明：本文仅供医学专业人员参考学习，具体诊疗请遵医嘱。</p><p><br></p>',4,'https://picsum.photos/seed/health1/400/250',NULL,1,1,'2026-06-01 20:33:41'),(14,'地中海饮食与心血管疾病的预防','<ol><li>什么是地中海饮食？</li></ol><p>地中海饮食（Mediterranean Diet）并非一种严格的、限制性的减肥食谱，而是一种泛指希腊、意大利南部、西班牙等环地中海国家传统的饮食习惯和生活方式。多次被美国《新闻与世界报道》（U.S. News & World Report）评为全球最佳整体饮食模式。</p><h2>2. 地中海饮食的核心构成</h2><p>地中海饮食金字塔强调以下几个层级：</p><ol><li>每日大量摄入（基础）： 蔬菜、水果、全谷物（燕麦、糙米、全麦）、豆类、坚果和种子。 特级初榨橄榄油作为主要的脂肪来源（替代黄油和猪油）。 大量的水。</li><li>每周适量摄入（中层）： 鱼类和海鲜（每周至少两次，特别是富含Omega-3的深海鱼如三文鱼、沙丁鱼）。 禽肉、鸡蛋和适量的乳制品（主要是酸奶和奶酪）。</li><li>极少量摄入（顶层）： 红肉（猪肉、牛肉、羊肉）和加工肉类（香肠、培根）。 甜点和含糖饮料。</li><li>生活方式的配合： 与家人朋友共享膳食，保持规律的体育活动。 成年人可适量饮用红酒（通常建议随餐饮用，女性每天不超过一杯，男性不超过两杯），但这并非强制要求。</li></ol><h2>3. 对心血管健康的保护机制</h2><p>地中海饮食在预防心脏病和中风方面有着强大的临床证据支持，其生理机制主要包括：</p><ul><li>改善血脂代谢：富含单不饱和脂肪酸（橄榄油）和多不饱和脂肪酸（深海鱼），有助于降低“坏胆固醇”（LDL-C）水平，升高“好胆固醇”（HDL-C）水平。</li><li>抗炎与抗氧化作用：大量的蔬菜、水果和坚果提供了丰富的维生素、矿物质、膳食纤维和植物化学物质（如多酚类），能有效中和体内的自由基，减轻系统性炎症反应（炎症是动脉粥样硬化的关键驱动因素）。</li><li>改善内皮功能：保持血管弹性，有助于稳定血压。</li><li>调节肠道菌群：高膳食纤维促进有益肠道细菌的生长，这些细菌产生的短链脂肪酸对代谢健康有益。</li></ul><h2>4. 常见问答 (Q&A)</h2><ul><li>Q：如果买不到特级初榨橄榄油，可以用什么代替？ A：如果条件受限，可以选择其他富含单不饱和脂肪酸的植物油，如茶籽油（被称为“东方橄榄油”）、芥花籽油（Canola oil）或花生油，但尽量避免使用油炸等高温烹饪方式。</li><li>Q：地中海饮食适合减肥吗？ A：虽然地中海饮食的初衷不是减肥，但由于其富含膳食纤维且提倡健康脂肪，能提供良好的饱腹感。如果在遵循地中海饮食原则的同时，适度控制总热量摄入，它可以成为一种非常健康、不易反弹的长期减重方式。</li></ul>',1,'https://picsum.photos/seed/health2/400/250',NULL,NULL,NULL,'2026-06-01 20:35:01'),(15,'常见急症鉴别诊断与院前处理','<h1><strong>一、急性胸痛</strong></h1><p>急性胸痛是急诊科最常见的危重症状之一，病因涵盖心源性、肺源性、消化源性等多个系统。快速鉴别至关重要。</p><h2><strong>1. 急性心肌梗死</strong></h2><p>典型表现：胸骨后压榨性疼痛，持续&gt;20分钟，可放射至左肩、左臂内侧、下颌或背部，常伴大汗、濒死感。含服硝酸甘油不缓解。</p><p>院前处理：立即停止一切活动，取半卧位，舌下含服硝酸甘油0.5mg（血压不低时），嚼服阿司匹林300mg（无过敏及出血禁忌），呼叫120。</p><p>关键检查：心电图（18导联）+ 心肌标志物（hs-cTnI、CK-MB）。</p><h2><strong>2. 肺栓塞</strong></h2><p>典型表现：突发胸痛+呼吸困难+咯血三联征，可伴晕厥、低血压。常有深静脉血栓危险因素（长期卧床、手术、肿瘤、妊娠等）。</p><p>关键检查：D-二聚体筛查 + CT肺动脉造影(CTPA)确诊。</p><h2><strong>3. 主动脉夹层</strong></h2><p>典型表现：突发撕裂样剧痛，疼痛部位可随夹层扩展而迁移，双上肢血压差&gt;20mmHg。</p><p>紧急处理：控制心率&lt;60次/分，收缩压降至100-120mmHg，立即转送血管外科。</p><h1><strong>二、急性腹痛</strong></h1><h2><strong>1. 急性阑尾炎</strong></h2><p>典型表现：转移性右下腹痛（脐周→右下腹），伴麦氏点压痛、反跳痛。可有低热、恶心呕吐、白细胞升高。</p><p>鉴别：需排除右侧输尿管结石、宫外孕破裂（女性）、肠系膜淋巴结炎（儿童）。</p><h2><strong>2. 急性胰腺炎</strong></h2><p>典型表现：暴饮暴食或饮酒后突发上腹剧烈持续性疼痛，向腰背部放射，屈曲体位可缓解。血清淀粉酶升高&gt;正常上限3倍。</p><p>严重度评估：Ranson评分≥3或CTSI≥4分为重症，死亡率可达30%。治疗核心：禁食+液体复苏+镇痛。</p><h2><strong>3. 肠梗阻</strong></h2><p>四大典型症状：腹痛、呕吐、腹胀、停止排便排气。腹部立位平片可见阶梯状气液平面。</p><p>紧急情况：绞窄性肠梗阻（持续剧烈腹痛+腹膜刺激征+发热）需紧急手术。</p><h1><strong>三、急性脑血管病（卒中）</strong></h1><p>时间就是大脑！溶栓时间窗：发病4.5小时内。</p><h2><strong>FAST快速识别法</strong></h2><table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">字母</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">含义</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">检查方法</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">F (Face)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">面部</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">微笑时口角是否歪斜</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">A (Arm)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">手臂</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">双上肢平举是否一侧下垂</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">S (Speech)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">语言</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">说话是否含糊不清或无法理解</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">T (Time)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">时间</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">出现任一症状立即拨打120</td></tr></tbody></table><h1><strong>四、过敏性休克</strong></h1><p>诱因：药物（青霉素最常见）、食物（坚果、海鲜）、昆虫叮咬。</p><p>识别：接触过敏原后数分钟至数小时内出现皮肤潮红/荨麻疹+呼吸窘迫+低血压，可伴喉头水肿、支气管痉挛。</p><p>急救：肾上腺素0.3-0.5mg大腿外侧肌注（1:1000），每5-15分钟可重复。同时建立静脉通路，快速补液。糖皮质激素和抗组胺药作为二线辅助治疗。</p><h1><strong>五、院前急救通用原则</strong></h1><p>1. DRABC评估：危险(Danger)→反应(Response)→气道(Airway)→呼吸(Breathing)→循环(Circulation)</p><p>2. 心肺复苏：按压频率100-120次/分，深度5-6cm，按压:通气=30:2</p><p>3. 止血：直接压迫止血，止血带仅用于危及生命的四肢大出血</p><p>4. 搬运：疑似脊柱损伤者需轴位翻身，颈椎损伤需颈托固定</p><p>5. 心理支持：对清醒患者进行安抚，告知已呼叫急救，减少恐惧和焦虑</p><p> </p><p>声明：本文仅供医学专业人员参考学习，具体诊疗请遵医嘱。紧急情况请立即拨打120。</p><p><br></p>',4,'https://picsum.photos/seed/health4/400/250',NULL,NULL,NULL,'2026-06-01 20:35:45'),(16,'儿童常见病家庭护理汇总','<p><br></p><p>一、小儿发热</p><p>1. 体温分级</p><p> &nbsp; - 低热：37.3-38.0℃</p><p> &nbsp; - 中度发热：38.1-39.0℃</p><p> &nbsp; - 高热：39.1-41.0℃</p><p> &nbsp; - 超高热：&gt;41.0℃</p><p><br></p><p>2. 退热药物选择</p><p> &nbsp; - 对乙酰氨基酚（扑热息痛）：10-15mg/kg/次，间隔4-6小时，每日不超过5次</p><p> &nbsp; - 布洛芬：5-10mg/kg/次，间隔6-8小时，每日不超过4次</p><p> &nbsp; - 不推荐交替使用，除非单一药物效果不佳且遵医嘱</p><p> &nbsp; - 3个月以下婴儿发热禁用退热药，立即就医</p><p><br></p><p>3. 物理降温</p><p> &nbsp; - 保持室内通风，室温22-25℃</p><p> &nbsp; - 减少衣物包裹，利于散热</p><p> &nbsp; - 温水擦浴（32-34℃）颈、腋、腹股沟，禁用酒精擦浴</p><p> &nbsp; - 多饮水，观察尿量（婴幼儿&gt;1ml/kg/h为正常）</p><p><br></p><p>4. 立即就医的警示信号</p><p> &nbsp; - 3月龄以下婴儿体温&gt;38℃</p><p> &nbsp; - 持续高热&gt;72小时</p><p> &nbsp; - 精神萎靡、嗜睡、烦躁不安</p><p> &nbsp; - 出现惊厥（热性惊厥）</p><p> &nbsp; - 呼吸急促（&lt;1岁&gt;50次/分，1-5岁&gt;40次/分）</p><p> &nbsp; - 皮肤出现紫癜或瘀斑（警惕脑膜炎球菌败血症）</p><p><br></p><p>二、小儿腹泻</p><p>1. 脱水程度判断</p><p> &nbsp; 轻度：口唇稍干，尿量略少，前囟/眼窝稍凹陷</p><p> &nbsp; 中度：皮肤弹性差，尿量明显减少，前囟/眼窝明显凹陷</p><p> &nbsp; 重度：意识改变，无尿&gt;6小时，四肢凉，脉搏细弱（立即就医）</p><p><br></p><p>2. 口服补液盐(ORS)</p><p> &nbsp; - 低渗ORS配方：氯化钠2.6g + 枸橼酸钠2.9g + 氯化钾1.5g + 无水葡萄糖13.5g + 水1000ml</p><p> &nbsp; - 原则：拉多少补多少，少量多次喂服</p><p> &nbsp; - 轻度脱水：50ml/kg，4小时内分次喝完</p><p> &nbsp; - 母乳喂养继续，辅食暂停生冷油腻</p><p><br></p><p>3. 常用药物</p><p> &nbsp; - 蒙脱石散：&lt;1岁 1g tid，1-2岁 1.5g tid，&gt;2岁 3g tid（空腹，与其它药物隔1h）</p><p> &nbsp; - 益生菌：双歧杆菌/布拉氏酵母菌，辅助恢复肠道菌群</p><p> &nbsp; - 锌制剂：6个月以下 10mg/天，6个月以上 20mg/天，连服10-14天</p><p> &nbsp; - 禁用成人止泻药（如洛哌丁胺，有中枢神经毒性风险）</p><p><br></p><p>三、手足口病</p><p>1. 病原：肠道病毒（柯萨奇A16、EV71最常见）</p><p>2. 典型表现：发热+手足臀丘疹/疱疹+口腔疱疹/溃疡</p><p>3. 高峰季节：5-7月，好发年龄：5岁以下</p><p>4. 隔离期：症状消失后1周，约10-14天</p><p>5. 重症预警（EV71感染）：持续高热&gt;3天 + 精神差/呕吐/肢体抖动 + 心率呼吸增快</p><p>6. 治疗：对症支持，无特效抗病毒药，EV71疫苗可预防</p><p><br></p><p>四、急性上呼吸道感染（感冒）</p><p>1. 90%为病毒感染，7-10天自愈</p><p>2. 不常规使用抗生素</p><p>3. 对症：鼻塞用生理盐水喷鼻，咳嗽&gt;1岁可服蜂蜜2-5ml</p><p>4. 6岁以下禁用复方感冒药（含减充血剂/抗组胺成分）</p><p>5. 并发症警示：耳痛（中耳炎）、呼吸急促（肺炎）、持续发热&gt;3天</p><p><br></p>',4,'https://picsum.photos/seed/health3/400/250',NULL,NULL,NULL,'2026-06-01 20:40:54'),(17,'一本小小的病理书','<p>头痛，发热，鼻塞，流涕，咽痛是由风寒感冒引起的1，需要开感冒灵颗粒</p>',4,'https://picsum.photos/seed/health3/400/250',NULL,NULL,NULL,'2026-06-01 20:44:20'),(18,'肥胖症的临床营养干预与减重策略','<h2>1. 肥胖症的定义与危害</h2><p>肥胖症是一种由多因素引起的慢性代谢性疾病，表现为体内脂肪过度积聚。临床上通常使用身体质量指数（BMI）来衡量：</p><ul><li>BMI = 体重(kg) / 身高(m)的平方</li><li>根据中国标准：BMI 24.0-27.9 为超重，BMI ≥ 28.0 为肥胖。</li></ul><p>肥胖是2型糖尿病、高血压、冠心病、阻塞性睡眠呼吸暂停综合征（OSAS）以及某些癌症（如乳腺癌、结肠癌）的独立危险因素。</p><h2>2. 减重的核心原理：能量负平衡</h2><p>所有成功的减重饮食干预，其底层逻辑都是创造<strong>能量缺口（Caloric Deficit）</strong>，即：<strong>总能量消耗 &gt; 总能量摄入</strong>。<br>通常建议每天创造 500-750 千卡的能量缺口，这样可以实现每周减轻 0.5-1.0 公斤体重的稳健目标。</p><h2>3. 常见的医学减重饮食模式</h2><h3>3.1 限能量平衡膳食 (CRD)</h3><ul><li>特点：在限制总热量摄入的同时，保持营养素比例平衡。碳水化合物占50%-60%，蛋白质占15%-20%，脂肪占20%-30%。</li><li>优势：安全性高，容易长期坚持，适合绝大多数肥胖患者。</li></ul><h3>3.2 高蛋白饮食 (HPD)</h3><ul><li>特点：提高蛋白质的摄入比例（通常占总热量的20%-30%，或每天1.5-2.0g/kg体重）。</li><li>机制：蛋白质的食物热效应（TEF）最高，消化吸收需要消耗更多热量；同时能增加饱腹感，并在减重期间最大限度地保留瘦体重（肌肉）。</li><li>禁忌：慢性肾脏病患者慎用。</li></ul><h3>3.3 间歇性禁食 (Intermittent Fasting, IF)</h3><ul><li>特点：不严格限制食物种类，而是限制进食的“时间窗口”。最流行的是 16:8 方案（每天禁食16小时，在8小时的窗口期内进食）。</li><li>机制：通过延长空腹时间，降低胰岛素水平，促使身体动用脂肪储备作为能量。</li><li>注意事项：进食窗口期内仍需控制总热量，不能暴饮暴食。孕妇、儿童及有进食障碍史者不宜采用。</li></ul><h2>4. 减重过程中的行为干预</h2><p>仅仅改变饮食内容是不够的，行为习惯的改变决定了减重能否长期维持：</p><ul><li>细嚼慢咽：大脑接收到饱腹信号通常需要20分钟，减慢进食速度可以减少总摄入量。</li><li>规律作息：睡眠不足会导致“瘦素”（抑制食欲）分泌减少，“饥饿素”分泌增加，导致食欲亢进，尤其是对高糖高脂食物的渴望。</li><li>情绪管理：识别并克服“情绪性进食”（因压力、焦虑或无聊而进食，而非真正的生理饥饿）。</li></ul><h2>5. 常见问答 (Q&A)</h2><ul><li>Q：为什么我减肥初期掉秤很快，后来就不动了（平台期）？ A：初期掉的体重很大一部分是水分和糖原。随着体重下降，身体的基础代谢率也会适应性降低（身体在“节能”），导致原先的能量缺口消失。打破平台期需要重新评估热量需求，或增加运动强度和力量训练。</li><li>Q：可以用果汁代替水果来减肥吗？ A：不建议。榨汁过程破坏了水果中的膳食纤维，并且果汁通常含有浓缩的果糖，消化吸收极快，不仅容易导致血糖飙升，而且饱腹感差，极易造成热量超标。</li></ul>',4,'https://picsum.photos/seed/health4/400/250',NULL,NULL,NULL,'2026-06-01 20:45:19'),(19,'高尿酸血症与痛风饮食管理指南','<p><br></p><p><br></p><p>一、诊断标准</p><p>- 高尿酸血症：非同日2次空腹血尿酸 &gt;420μmol/L(男性) 或 &gt;360μmol/L(女性)</p><p>- 痛风：高尿酸血症+关节红肿热痛+关节液检出尿酸盐结晶</p><p><br></p><p>二、降尿酸目标值</p><p>- 普通高尿酸血症：&lt;360μmol/L</p><p>- 痛风患者（无痛风石）：&lt;360μmol/L</p><p>- 痛风患者（有痛风石）：&lt;300μmol/L</p><p>- 不推荐长期 &lt;180μmol/L</p><p><br></p><p>三、嘌呤含量分级与食物选择</p><p><br></p><p>高嘌呤食物（150-1000mg/100g，急性期禁食，缓解期严格限制）</p><p> &nbsp;- 动物内脏：猪肝(229)、猪肾(226)、鸡肝(243)</p><p> &nbsp;- 海鲜：沙丁鱼(295)、鲭鱼(210)、贝类、虾蟹、鱼籽</p><p> &nbsp;- 浓肉汤、火锅汤底(嘌呤溶于水，熬煮后极高)</p><p> &nbsp;- 红肉：牛肉、猪肉、羊肉（缓解期&lt;100g/天）</p><p><br></p><p>中嘌呤食物（50-150mg/100g，缓解期可适量）</p><p> &nbsp;- 白肉：去皮鸡肉、鸭肉</p><p> &nbsp;- 部分鱼类：三文鱼、鳕鱼、鲤鱼</p><p> &nbsp;- 豆类及豆制品：豆腐、豆浆、豌豆（植物嘌呤对血尿酸影响远小于动物嘌呤）</p><p> &nbsp;- 菌菇类：香菇、金针菇</p><p><br></p><p>低嘌呤食物（&lt;50mg/100g，可自由选择）</p><p> &nbsp;- 主食类：米饭、面条、馒头、玉米、土豆</p><p> &nbsp;- 蔬菜类：绝大多数叶菜、瓜果类蔬菜</p><p> &nbsp;- 水果类：苹果、梨、桃（但应限制高果糖水果：西瓜、荔枝）</p><p> &nbsp;- 奶制品：低脂/脱脂牛奶、酸奶（促进尿酸排泄）</p><p> &nbsp;- 蛋类：鸡蛋、鸭蛋（极低嘌呤优质蛋白）</p><p><br></p><p>四、饮水管理</p><p>- 每日饮水量 2000-3000ml，保证尿量&gt;2000ml/天</p><p>- 推荐：白开水、淡茶、苏打水（弱碱性）</p><p>- 禁忌：含糖饮料、果汁（果糖代谢产生尿酸）、啤酒（含鸟嘌呤核苷）</p><p><br></p><p>五、药物干预指征</p><p>启动降尿酸药物治疗的条件（满足任一）：</p><p>1. 痛风发作≥2次/年</p><p>2. 有痛风石或关节尿酸沉积证据</p><p>3. 合并慢性肾脏病(CKD 3期以上)</p><p>4. 血尿酸持续&gt;540μmol/L(9mg/dL)</p><p><br></p><p>六、常用降尿酸药物</p><p>1. 别嘌醇：抑制尿酸生成。起始100mg/天，最大600mg/天。HLA-B*5801阳性者禁用（亚裔高发，可致严重超敏反应综合征）</p><p>2. 非布司他：抑制尿酸生成。起始20-40mg/天，最大80mg/天。心血管疾病患者慎用</p><p>3. 苯溴马隆：促进尿酸排泄。eGFR&lt;20ml/min禁用。服药期间需大量饮水并碱化尿液</p><p><br></p><p>七、急性痛风发作处理</p><p>- 尽早用药（发作24小时内效果最佳）</p><p>- 一线：秋水仙碱（首剂1mg，1小时后再服0.5mg，之后0.5mg bid/tid）</p><p>- 二线：非甾体抗炎药（如依托考昔、塞来昔布）</p><p>- 三线：糖皮质激素（如泼尼松30-40mg/天）</p><p>- 发作期不启动/不调整降尿酸药（避免尿酸盐波动诱发加重）</p><p><br></p>',1,'https://picsum.photos/seed/health5/400/250',NULL,NULL,NULL,'2026-06-01 20:46:39'),(20,'高血压患者日常管理指南','<p>一、血压分级标准</p><p>正常血压：收缩压 &lt; 120 mmHg 且 舒张压 &lt; 80 mmHg</p><p>正常高值：收缩压 120-139 mmHg 或 舒张压 80-89 mmHg</p><p>高血压1级：收缩压 140-159 mmHg 或 舒张压 90-99 mmHg</p><p>高血压2级：收缩压 160-179 mmHg 或 舒张压 100-109 mmHg</p><p>高血压3级：收缩压 &gt;= 180 mmHg 或 舒张压 &gt;= 110 mmHg</p><p><br></p><p>二、生活方式干预</p><p>1. 限盐：每日食盐摄入量 &lt; 6g，避免腌制食品和高钠调味品</p><p>2. 减重：BMI 控制在 18.5-23.9 kg/m²，腰围男性 &lt; 90cm，女性 &lt; 85cm</p><p>3. 运动：每周至少 150 分钟中等强度有氧运动（快走、游泳、骑车）</p><p>4. 戒烟限酒：彻底戒烟，酒精摄入男性 &lt; 25g/天，女性 &lt; 15g/天</p><p>5. DASH饮食：增加蔬菜、水果、全谷物、低脂乳制品摄入</p><p><br></p><p>三、常用降压药物分类</p><p>1. 钙通道阻滞剂(CCB)：如氨氯地平、硝苯地平控释片</p><p>2. ACEI类：如依那普利、培哚普利</p><p>3. ARB类：如缬沙坦、厄贝沙坦</p><p>4. 利尿剂：如氢氯噻嗪、吲达帕胺</p><p>5. β受体阻滞剂：如美托洛尔、比索洛尔</p><p><br></p><p>四、监测与随访</p><p>- 家庭自测血压每日早晚各1次，每次测2-3遍取平均值</p><p>- 每3-6个月复查血脂、血糖、肾功能、电解质</p><p>- 每年做一次超声心动图、颈动脉超声</p><p><br></p><p>五、危险信号（需立即就医）</p><p>- 收缩压 &gt; 180 mmHg 或舒张压 &gt; 120 mmHg 伴有头痛、视物模糊</p><p>- 突发胸痛、呼吸困难、一侧肢体无力、言语不清</p><p><br></p>',5,'https://picsum.photos/seed/health1/400/250',NULL,NULL,NULL,'2026-06-01 20:47:11'),(21,'骨质疏松症防治指南','<h1><strong>一、定义</strong></h1><p>骨质疏松症是一种以骨量减少、骨微结构破坏、骨脆性增加、易发生骨折为特征的全身性骨病。分为：原发性（绝经后骨质疏松I型、老年性骨质疏松II型）和继发性（药物、疾病导致）。</p><h1><strong>二、诊断标准（WHO标准）</strong></h1><p>基于双能X线吸收法(DXA)测定骨密度T值：</p><table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">诊断</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">T值</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">处理建议</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">正常</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">T ≥ -1.0</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">保持健康生活方式</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">骨量减少</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">-2.5 &lt; T &lt; -1.0</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">补充钙+维生素D，生活方式干预</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">骨质疏松</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">T ≤ -2.5</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">启动药物治疗</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">严重骨质疏松</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">T ≤ -2.5 + 脆性骨折</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">强化治疗方案</td></tr></tbody></table><h1><strong>三、骨转换标志物监测</strong></h1><p>骨形成标志物：PINP（I型原胶原N端前肽，最敏感）、ALP（骨性碱性磷酸酶）</p><p>骨吸收标志物：β-CTX（I型胶原C末端肽交联，最常用）、NTX（I型胶原N末端肽）</p><p>临床意义：抗骨吸收治疗3-6个月后，β-CTX应下降&gt;30%，否则需评估依从性或调整方案</p><h1><strong>四、基础治疗：钙与维生素D</strong></h1><p>推荐每日摄入量：</p><p>钙：成人800-1200mg/天（分次口服，单次≤500mg吸收最佳），饮食+补充剂总量</p><p>高钙食物：牛奶(120mg/100ml)、酸奶(150mg/100g)、豆腐(164mg/100g)、芝麻酱(1170mg/100g)、虾皮(991mg/100g)、深绿色蔬菜(油菜、芥蓝)</p><p>维生素D3：800-1200 IU/天，维持血清25(OH)D≥30ng/mL（75nmol/L）</p><p>活性维生素D及其类似物：骨化三醇/阿法骨化醇，适用于肝肾功能不全或老年人</p><h1><strong>五、抗骨质疏松药物</strong></h1><h2><strong>1. 双膦酸盐类（一线首选）</strong></h2><p>作用机制：抑制破骨细胞活性，降低骨吸收</p><p>阿仑膦酸钠：70mg 每周1次，晨起空腹&gt;200ml白水送服，服药后保持直立30分钟</p><p>唑来膦酸：5mg 静脉滴注 每年1次（方便性最好，依从性最佳）</p><p>警示：严重肾损害(eGFR&lt;35)禁用；双膦酸盐使用前需检查口腔，治疗期间避免拔牙等口腔手术（颌骨坏死风险）</p><h2><strong>2. RANKL抑制剂</strong></h2><p>地舒单抗：60mg 皮下注射 每6个月1次</p><p>优势：肾功能不全者无需调整剂量；可提高骨密度幅度优于双膦酸盐</p><p>注意：停药后骨吸收反弹性升高(反弹效应)，不可随意停药/推迟给药</p><h2><strong>3. 骨形成促进剂（合成代谢剂）</strong></h2><p>特立帕肽（重组人PTH 1-34）：20μg 皮下注射 qd，疗程≤24个月</p><p>适应症：严重骨质疏松(T≤-3.5)、椎体骨折≥2处、双膦酸盐治疗效果欠佳</p><p>禁忌：Paget骨病、既往骨骼放疗史、骨转移、高钙血症、妊娠/哺乳</p><h1><strong>六、康复与运动</strong></h1><p>核心目标：增强肌力→改善平衡→降低跌倒率→减少骨折</p><p>1. 负重运动（刺激骨形成）：快走、慢跑、爬楼梯、跳舞，每周3-5次，每次30分钟</p><p>2. 抗阻运动（增强肌肉）：弹力带、哑铃训练，每周2-3次</p><p>3. 平衡训练（防跌倒）：太极拳、单腿站立练习，每天10-15分钟</p><p>4. 姿势训练：避免前屈运动（如仰卧起坐）、剧烈扭转动作</p><p>5. 骨折急性期：伤后1-2周绝对卧床→2-4周床上四肢活动→4-8周坐起→3个月后助行器行走</p><h1><strong>七、防跌倒家庭改造</strong></h1><p>1. 移除地面障碍物、散落的电线</p><p>2. 浴室安装扶手+防滑垫，马桶座圈适当加高</p><p>3. 夜间照明充足，床头到卫生间沿途设置小夜灯</p><p>4. 穿防滑鞋，避免穿拖鞋</p><p>5. 视力矫正：定期眼科检查，白内障及早手术</p><h1><strong>八、药物治疗疗程与药物假期</strong></h1><p>口服双膦酸盐：治疗3-5年后评估是否进入药物假期（骨折风险不高时可停药1-2年观察）</p><p>静脉唑来膦酸：治疗3年后评估，高风险者继续至6年</p><p>地舒单抗：无药物假期概念，需持续给药或转换为双膦酸盐过渡</p><p>特立帕肽：疗程上限24个月，停药后序贯双膦酸盐/地舒单抗维持疗效</p><p><br></p><p>声明：本文仅供医学专业人员参考学习，具体诊疗请遵医嘱。</p><p><br></p>',4,'https://picsum.photos/seed/health4/400/250',NULL,NULL,NULL,'2026-06-01 20:48:07'),(22,'冠心病康复与二级预防指南','<p>一、冠心病分型</p><p>1. 慢性冠脉综合征(CCS)：稳定型心绞痛、缺血性心肌病</p><p>2. 急性冠脉综合征(ACS)：ST段抬高型心梗(STEMI)、非ST段抬高型心梗(NSTEMI)、不稳定型心绞痛</p><p><br></p><p>二、二级预防核心策略(ABCDE)</p><p>A — 抗血小板与ACEI/ARB</p><p> &nbsp;- 阿司匹林 100mg qd 终身服用（无禁忌），PCI术后需联合氯吡格雷/替格瑞洛双抗</p><p> &nbsp;- ACEI/ARB：改善心室重构，目标血压&lt;130/80mmHg</p><p>B — 血压与β受体阻滞剂</p><p> &nbsp;- 美托洛尔/比索洛尔：降低心肌氧耗，目标静息心率55-60次/分</p><p> &nbsp;- 血压目标&lt;130/80mmHg，老年人可放宽至&lt;140/90mmHg</p><p>C — 胆固醇管理与戒烟</p><p> &nbsp;- LDL-C目标：极高危&lt;1.4mmol/L(55mg/dL)，高危&lt;1.8mmol/L(70mg/dL)</p><p> &nbsp;- 他汀类药物+必要时联合依折麦布/PCSK9抑制剂</p><p> &nbsp;- 彻底戒烟，避免二手烟</p><p>D — 饮食与糖尿病管理</p><p> &nbsp;- 地中海饮食：橄榄油、坚果、深海鱼、蔬果为主</p><p> &nbsp;- 糖化血红蛋白 HbA1c&lt;7.0%</p><p>E — 运动与教育</p><p> &nbsp;- 每周≥150min中等强度有氧运动</p><p> &nbsp;- 心肺康复评估：6分钟步行试验、心肺运动试验</p><p><br></p><p>三、心绞痛分级(CCS分级)</p><p>I级：重体力活动诱发心绞痛</p><p>II级：日常活动轻度受限（快走、爬坡时发作）</p><p>III级：日常活动明显受限（慢走1-2条街即发作）</p><p>IV级：轻微活动或静息时即发作</p><p><br></p><p>四、硝酸酯类药物使用规范</p><p>- 舌下含服硝酸甘油0.5mg，5分钟后不缓解可重复1次，最多3次</p><p>- 15分钟仍不缓解+持续胸痛，高度怀疑急性心梗，立即呼叫120</p><p>- 硝酸酯类24小时内应有10-12小时无药间歇，避免耐药</p><p><br></p><p>五、康复分期</p><p>1. 住院期(I期)：床上被动活动→坐起→床边站立→室内慢走</p><p>2. 恢复期(II期)：出院后1-6个月，每周3-5次有氧运动，心率=静息心率+20~30次/分</p><p>3. 维持期(III期)：长期规律运动，回归社会角色</p><p><br></p><p>六、危险信号</p><p>- 静息心绞痛或心绞痛频率/程度突然加重</p><p>- 含服硝酸甘油无效的胸痛持续&gt;15分钟</p><p>- 突发呼吸困难、端坐呼吸、双下肢水肿（警惕心衰）</p>',4,'https://picsum.photos/seed/health2/400/250',NULL,NULL,NULL,'2026-06-01 20:48:57'),(23,'临床合理用药基本原则','<h2>一、合理用药五大原则</h2><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">原则</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">内涵</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>安全性</strong></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">用药风险小于获益。注意禁忌症、不良反应监测、特殊人群剂量调整</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>有效性</strong></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">选择循证医学证据充分的药物和方案</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>经济性</strong></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">在安全有效前提下，优选成本效果比最优的方案</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>适当性</strong></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">选对药、用对量、走对途径、给对疗程</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"><strong>个体化</strong></td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">结合患者基因型、肝肾功能、年龄、合并用药制定方案</td></tr></tbody></table><hr/><p><br></p><h2>二、特殊人群用药</h2><h3>老年人用药</h3><ul><li>起始剂量为成人剂量的1/2-2/3，缓慢滴定</li><li>五种以上药物联用时评估药物相互作用（Beers标准筛查潜在不合理用药）</li><li>慎用苯二氮卓类、抗胆碱能药、NSAIDs（肾损害+消化道出血风险高）</li></ul><h3>妊娠期用药</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">FDA分级</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">定义</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">示例</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">A级</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">对照研究证实对胎儿无风险</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">左甲状腺素、叶酸</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">B级</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">动物实验中未见风险或无人类数据</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">青霉素类、头孢菌素、胰岛素</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">C级</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">动物实验中显示不良反应，缺乏人类数据</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">沙丁胺醇、钙通道阻滞剂</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">D级</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">人类数据显示对胎儿有风险，但获益可能大于风险</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">卡马西平、丙戊酸钠、华法林</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">X级</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">动物和人类已证实致畸，妊娠期绝对禁用</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">异维A酸、沙利度胺、他汀类</td></tr></tbody></table><h3>哺乳期用药</h3><ul><li>大多数药物以低浓度进入乳汁（&lt;母体剂量的1-2%）</li><li>哺乳后立即服药可减少乳汁中药物浓度峰值</li><li>安全选项：对乙酰氨基酚、布洛芬、青霉素类</li></ul><hr/><p><br></p><h2>三、肝肾功能不全剂量调整</h2><h3>肾功能不全（以eGFR为参考）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">eGFR (ml/min/1.73m²)</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">调整方案</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&gt;60</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常剂量</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">30-60</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">部分药物需减量25-50%或延长给药间隔</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">15-30</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">多数药物需显著减量</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;15 或透析</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">参照透析用药指南调整</td></tr></tbody></table><p><strong>常见需要肾功能调整的药物：</strong></p><ul><li>抗生素：头孢类、喹诺酮类、氨基糖苷类（肾毒性，CKD慎用）、万古霉素</li><li>抗病毒药：阿昔洛韦、更昔洛韦</li><li>降糖药：二甲双胍（eGFR&lt;30禁用，eGFR 30-45减量不超过1g/天）</li><li>NSAIDs：CKD 3期以上尽量避免</li><li>低分子肝素：治疗剂量时需监测抗Xa因子活性</li></ul><h3>肝功能不全（Child-Pugh分级）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">分级</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">A级（轻度）</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">B级（中度）</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">C级（重度）</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">胆红素(mg/dL)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;2</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">2-3</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&gt;3</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">白蛋白(g/L)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&gt;35</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">28-35</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;28</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">PT延长(秒)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;4</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">4-6</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&gt;6</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">腹水</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">无</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">可控</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">难治</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">脑病</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">无</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">1-2级</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">3-4级</td></tr></tbody></table><hr/><p><br></p><h2>四、药物相互作用警示</h2><h3>药效学相互作用（同侧效应叠加）</h3><ul><li>非甾体抗炎药+糖皮质激素 → 消化道出血风险倍增</li><li>镇静催眠药+酒精 → 呼吸抑制</li><li>ACEI+保钾利尿剂 → 高钾血症</li></ul><h3>药代动力学相互作用（代谢酶CYP450介导）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">机制</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">代表药</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">联用后果</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP3A4抑制剂+他汀</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">酮康唑/克拉霉素+阿托伐他汀</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">横纹肌溶解风险</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP2C19抑制剂+氯吡格雷</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">奥美拉唑+氯吡格雷</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">抗血小板效果减弱</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP2C9诱导剂+华法林</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">利福平+华法林</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">抗凝不足 → 血栓</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">P-gp抑制剂+地高辛</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">胺碘酮+地高辛</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">地高辛中毒(心律失常)</td></tr></tbody></table><h3>常用CYP酶诱导剂和抑制剂</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP酶</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">诱导剂</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">抑制剂</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP3A4</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">利福平、卡马西平、苯妥英钠、圣约翰草</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">酮康唑、伊曲康唑、克拉霉素、葡萄柚汁</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP2C9</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">利福平</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">氟康唑、胺碘酮</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP2C19</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">利福平</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">奥美拉唑、氟西汀</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYP2D6</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">—</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">氟西汀、帕罗西汀、奎尼丁</td></tr></tbody></table><hr/><p><br></p><h2>五、抗生素合理使用</h2><h3>抗菌药物分级管理</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">级别</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">特点</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">代表药</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">非限制使用</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">安全有效、经济</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">青霉素G、阿莫西林、头孢氨苄</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">限制使用</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">针对特定病原菌</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">头孢曲松、左氧氟沙星、万古霉素</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">特殊使用</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">最后防线</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">碳青霉烯类、替加环素、利奈唑胺</td></tr></tbody></table><h3>抗生素使用六不原则</h3><ol><li>病毒感染不用（普通感冒90%为病毒性）</li><li>不明原因发热不用（除非有明确感染灶）</li><li>预防性使用不滥用（仅限于围手术期等明确指征）</li><li>能用窄谱不用广谱</li><li>能用单药不用联合（除非混合感染或协同需求）</li><li>疗程足而不超（一般7-14天，特殊感染按指南延长）</li></ol><p><br></p>',4,'https://picsum.photos/seed/health2/400/250',NULL,NULL,NULL,'2026-06-01 20:49:50'),(24,'营养学基础：宏量营养素与微量营养素','<h2>1. 概述</h2><p>营养学是研究食物中对人体有益的成分（营养素）以及它们在体内消化、吸收、代谢和排泄过程的科学。人体需要的营养素主要分为两大部分：宏量营养素（Macronutrients）和微量营养素（Micronutrients），此外还包括水和膳食纤维。</p><h2>2. 宏量营养素</h2><p>宏量营养素是人体需求量较大、能够提供能量的营养物质。</p><h3>2.1 碳水化合物 (Carbohydrates)</h3><ul><li>功能：人体最主要、最经济的能量来源，尤其是大脑和神经系统的主要燃料。1克碳水化合物提供约 4 千卡能量。</li><li>分类： 简单碳水化合物：单糖（如葡萄糖、果糖）和双糖（如蔗糖、乳糖），消化吸收快，易引起血糖波动。 复杂碳水化合物：多糖（如淀粉、糖原），消化吸收较慢，提供持久能量。</li><li>食物来源：谷物、薯类、豆类、水果等。</li></ul><h3>2.2 蛋白质 (Proteins)</h3><ul><li>功能：构成和修复身体组织（肌肉、骨骼、皮肤等），合成酶、激素和抗体，维持酸碱平衡。1克蛋白质提供约 4 千卡能量。</li><li>组成：由氨基酸组成。人体有9种必需氨基酸无法自行合成，必须通过食物获取。</li><li>食物来源： 优质蛋白：肉类、家禽、鱼类、蛋类、奶制品、大豆及其制品。 非完全蛋白：部分谷物和蔬菜。</li></ul><h3>2.3 脂肪 (Fats/Lipids)</h3><ul><li>功能：提供高密度能量（1克脂肪提供约 9 千卡能量），保护内脏器官，维持体温，促进脂溶性维生素（A、D、E、K）的吸收。</li><li>分类： 饱和脂肪酸：多存在于动物脂肪、椰子油中，摄入过多与心血管疾病风险增加有关。 不饱和脂肪酸：包括单不饱和脂肪酸（橄榄油、坚果）和多不饱和脂肪酸（鱼油中的Omega-3，植物油中的Omega-6），对心血管健康有益。 反式脂肪酸：存在于部分加工食品中，对健康极为有害，应尽量避免。</li></ul><h2>3. 微量营养素</h2><p>微量营养素虽然人体需求量极小，但对维持正常生理功能至关重要，几乎不提供能量。</p><h3>3.1 维生素 (Vitamins)</h3><ul><li>脂溶性维生素：维生素A（视力、免疫）、维生素D（骨骼健康、钙吸收）、维生素E（抗氧化）、维生素K（凝血功能）。</li><li>水溶性维生素：维生素C（抗氧化、胶原蛋白合成）、B族维生素（参与能量代谢和神经系统功能）。</li></ul><h3>3.2 矿物质 (Minerals)</h3><ul><li>常量元素：钙（骨骼和牙齿）、磷、钾、钠、镁。</li><li>微量元素：铁（氧气运输）、锌（免疫功能、伤口愈合）、碘（甲状腺功能）、硒（抗氧化）。</li></ul><h2>4. 常见问答 (Q&A)</h2><ul><li>Q：什么是“空热量”食物？ A：指那些含有高热量（通常来自添加糖和固体脂肪）但几乎不含维生素、矿物质、蛋白质或膳食纤维等必需营养素的食物，如碳酸饮料、薯片和糖果。</li><li>Q：为什么膳食纤维很重要，虽然它不能被消化？ A：膳食纤维可以增加饱腹感，促进肠道蠕动，预防便秘；可溶性纤维还有助于降低血液胆固醇水平和稳定血糖。</li></ul>',1,'https://picsum.photos/seed/health3/400/250',NULL,NULL,NULL,'2026-06-01 20:50:32'),(25,'孕期营养与围产保健管理','<h1><strong>一、孕期体重增长推荐（IOM标准）</strong></h1><table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">孕前BMI(kg/m²)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">推荐总增重(kg)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">孕中晚期增重速率(kg/周)</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">低体重 &lt;18.5</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">12.5 - 18</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">0.44 - 0.58</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">正常体重 18.5-24.9</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">11.5 - 16</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">0.35 - 0.50</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">超重 25-29.9</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">7 - 11.5</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">0.23 - 0.33</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">肥胖 ≥30</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">5 - 9</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">0.17 - 0.27</td></tr></tbody></table><h1><strong>二、关键营养素补充</strong></h1><h2><strong>1. 叶酸（预防神经管缺陷）</strong></h2><p>剂量：孕前3个月至孕早期(12周) 400-800μg/天</p><p>高危人群（既往NTD妊娠史/抗癫痫药）增至4-5mg/天</p><p>食物来源：深绿色叶菜(菠菜、芦笋)、豆类、动物肝脏、强化谷物</p><h2><strong>2. 铁（预防缺铁性贫血）</strong></h2><p>妊娠期铁需求量：约1000mg（红细胞增加+胎儿+胎盘+分娩失血储备）</p><p>孕中期开始常规补铁30-60mg/天（与维生素C同服促进吸收，避免与钙/茶同服）</p><p>缺铁性贫血诊断：Hb&lt;110g/L(孕期)，&lt;100g/L(产后)，血清铁蛋白&lt;15μg/L</p><p>食物来源：红肉、动物肝脏(每周1-2次&lt;100g)、动物血、黑木耳</p><h2><strong>3. 钙</strong></h2><p>推荐量：孕期/哺乳期 1000-1200mg/天</p><p>低钙摄入地区额外补钙1500-2000mg/天可降低子痫前期风险</p><p>食物来源：牛奶及奶制品(首选)、豆腐、芝麻酱(钙含量极高)、虾皮</p><h2><strong>4. 碘</strong></h2><p>孕期甲状腺激素合成增加50%，需额外补碘150μg/天</p><p>使用碘盐是基础，孕期建议含碘复合维生素</p><h2><strong>5. DHA（二十二碳六烯酸）</strong></h2><p>每日≥200mg，促进胎儿大脑和视网膜发育</p><p>食物来源：深海鱼(三文鱼、沙丁鱼，每周2次)、藻油DHA补充剂</p><p>注意事项：避免含汞高的鱼类(鲨鱼、旗鱼、方头鱼、大耳马鲛)</p><h1><strong>三、产前检查时间表</strong></h1><table style=\"width: auto;\"><tbody><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">孕周</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">检查项目</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">要点</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">6-8周</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">超声确认宫内孕、胎心</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">排除宫外孕</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">11-13+6周</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">NT超声+早期唐筛(NIPT可选)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">NT&lt;2.5mm为正常</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">16-20周</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">中孕期血清学筛查(唐筛)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">三联/四联筛查</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">20-24周</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">系统超声大排畸</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">全面筛查胎儿结构异常</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">24-28周</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">OGTT口服糖耐量试验</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">筛查妊娠期糖尿病GDM</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">28-32周</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">血常规+肝肾功能</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">筛查贫血、胆汁淤积</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">36周后</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">每周胎心监护(NST)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"384\">评估胎盘功能</td></tr></tbody></table><h1><strong>四、妊娠期常见问题处理</strong></h1><h2><strong>1. 妊娠剧吐</strong></h2><p>轻度：少食多餐、晨起前吃苏打饼干、生姜茶、维生素B6 10-25mg tid</p><p>重度（体重下降&gt;5%+酮症+电解质紊乱）：静脉补液+维生素B1(预防Wernicke脑病)+止吐药</p><p>止吐药物：多西拉敏+维生素B6(一线)，昂丹司琼(二线，孕早期尽量避免)</p><h2><strong>2. 妊娠期糖尿病(GDM)</strong></h2><p>OGTT诊断标准：空腹&lt;5.1，1h&lt;10.0，2h&lt;8.5 mmol/L，任一超标即诊断</p><p>管理目标：空腹&lt;5.3，餐后1h&lt;7.8，餐后2h&lt;6.7 mmol/L</p><p>生活方式干预2周血糖不达标启动胰岛素治疗（二甲双胍/格列本脲也可选择）</p><h2><strong>3. 妊娠期高血压疾病</strong></h2><p>妊娠期高血压：孕20周后新发血压≥140/90，无蛋白尿</p><p>子痫前期：血压≥140/90 + 蛋白尿≥300mg/24h 或 尿蛋白/肌酐≥0.3</p><p>重度子痫前期（任一）：血压≥160/110 + 血小板减少 + 肝酶升高 + 肺水肿 + 持续头痛/视力障碍</p><p>处理原则：解痉(硫酸镁)+降压(拉贝洛尔/硝苯地平)+适时终止妊娠</p><p>阿司匹林100-150mg/天口服用于子痫前期高风险孕妇的预防（孕12-16周开始至36周）</p><p><br></p><p>声明：本文仅供医学专业人员参考学习，具体诊疗请遵医嘱。</p><p><br></p>',100,'https://picsum.photos/seed/health4/400/250',NULL,NULL,NULL,'2026-06-01 20:51:45'),(26,'常见肿瘤标志物临床解读手册','<p><br></p><blockquote>重要提示：肿瘤标志物升高≠癌症确诊，仅为辅助参考指标，确诊需依靠病理活检。单项轻度升高需结合影像学+临床症状综合判断，动态监测趋势比单次绝对值更有意义。</blockquote><hr/><p><br></p><h2>一、广谱肿瘤标志物</h2><h3>CEA（癌胚抗原）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">项目</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">说明</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常值</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;5 ng/mL（非吸烟者），&lt;10 ng/mL（吸烟者）</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">相关肿瘤</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">结直肠癌、胃癌、肺癌、胰腺癌、乳腺癌</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">非癌性升高</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">吸烟、肝炎、肝硬化、溃疡性结肠炎、胰腺炎</td></tr></tbody></table><p><strong>临床意义：</strong></p><ul><li>结直肠癌术后监测：术后6周应恢复正常，持续升高提示复发/转移</li><li>辅助化疗疗效评估：2周期化疗后下降&gt;30%提示有效</li><li>胸水/腹水CEA&gt;血清CEA提示恶性积液</li></ul><hr/><p><br></p><h3>CA19-9（糖类抗原19-9）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">项目</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">说明</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常值</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;37 U/mL</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">相关肿瘤</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">胰腺癌（敏感性70-80%）、胆管癌、胃癌、结直肠癌</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">非癌性升高</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">急性胰腺炎、胆管炎、肝硬化、糖尿病</td></tr></tbody></table><p><strong>临床意义：</strong></p><ul><li>胰腺癌首选肿瘤标志物，但特异性有限</li><li>联合CA125对卵巢癌、联合CA242对胰腺癌提高诊断价值</li><li>Lewis血型阴性人群（约5-10%）CA19-9始终不升高</li></ul><hr/><p><br></p><h2>二、器官特异性肿瘤标志物</h2><h3>AFP（甲胎蛋白）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">项目</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">说明</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常值</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;20 ng/mL</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">相关肿瘤</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">原发性肝细胞癌(HCC)、卵黄囊瘤、胚胎性癌</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">非癌性升高</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">妊娠、急慢性肝炎、肝硬化（通常&lt;400ng/mL）</td></tr></tbody></table><p><strong>诊断阈值：</strong></p><ul><li>AFP&gt;400 ng/mL持续&gt;4周 → 高度怀疑HCC</li><li>AFP&gt;200 ng/mL持续&gt;8周 → 高度怀疑HCC</li><li>肝硬化患者AFP逐步升高需每3个月超声+AFP监测</li></ul><hr/><p><br></p><h3>CA125（糖类抗原125）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">项目</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">说明</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常值</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;35 U/mL</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">相关肿瘤</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">卵巢上皮癌（敏感性80-85%）、子宫内膜癌</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">非癌性升高</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">月经期、妊娠、子宫内膜异位症、盆腔炎、腹水、心衰</td></tr></tbody></table><p><strong>临床应用：</strong></p><ul><li>卵巢癌术后监测金标准</li><li>联合HE4+ROMA指数提高卵巢癌预测准确率</li><li>胸腹水CA125升高也可见于结核性胸腹膜炎</li></ul><hr/><p><br></p><h3>PSA（前列腺特异性抗原）</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">项目</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">说明</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常值</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">tPSA&lt;4 ng/mL</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">灰区</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">tPSA 4-10 ng/mL（需结合fPSA/fPSA比值）</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">高风险</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">fPSA/tPSA&lt;0.15 → 前列腺癌风险&gt;50%</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">fPSA/tPSA&gt;0.25 → 良性增生可能性大</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\"></td></tr></tbody></table><p><strong>影响因素：</strong></p><ul><li>年龄增长PSA自然升高（40-49岁&lt;2.5，50-59岁&lt;3.5，60-69岁&lt;4.5）</li><li>前列腺按摩、导尿、膀胱镜检查后2周内禁测PSA</li><li>5α-还原酶抑制剂（非那雄胺）服药6个月后PSA降低约50%</li></ul><hr/><p><br></p><h2>三、肺癌常用标志物</h2><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">标志物</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常值</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">敏感性最高的病理类型</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CYFRA21-1</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;3.3 ng/mL</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">肺鳞癌</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">CEA</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;5 ng/mL</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">肺腺癌</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">NSE</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;16.3 ng/mL</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">小细胞肺癌(SCLC)</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">ProGRP</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;50 pg/mL</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">小细胞肺癌(SCLC)，特异性更高</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">SCC-Ag</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;1.5 ng/mL</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">肺鳞癌</td></tr></tbody></table><hr/><p><br></p><h2>四、随访监测原则</h2><ol><li><strong>肿瘤标志物单项轻度升高</strong>（&lt;正常值上限2倍）：1个月后复查，若继续升高安排影像学</li><li><strong>术后标志物下降后再次升高</strong>：高度警惕复发转移，立即安排增强CT/PET-CT</li><li><strong>化疗期间一过性升高</strong>：可能是肿瘤溶解释放，2-3周后复查</li><li><strong>多标志物联合监测</strong>优于单项：如结直肠癌CEA+CA19-9，卵巢癌CA125+HE4</li></ol>',100,'https://picsum.photos/seed/health6/400/250',NULL,NULL,NULL,'2026-06-01 20:52:51'),(27,'消化系统常见疾病诊疗要点','<h1></h1><h2>一、胃食管反流病(GERD)</h2><h3>典型症状</h3><ul><li>烧心（胸骨后烧灼感）+ 反流（胃内容物向上反流至咽部或口腔）</li><li>多在餐后1小时内、平卧或弯腰时加重</li></ul><h3>警报症状（需胃镜检查排除肿瘤）</h3><ul><li>年龄&gt;45岁首发</li><li>吞咽困难、进行性体重下降</li><li>上消化道出血（黑便、呕血）</li><li>贫血</li></ul><h3>治疗阶梯</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">阶梯</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">方案</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">疗程</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">一</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">PPI标准剂量 qd（奥美拉唑20mg/泮托拉唑40mg）</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">4-8周</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">二</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">PPI标准剂量 bid</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">8周</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">三</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">PPI+促动力药（莫沙必利5mg tid）</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">个体化</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">维持</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">PPI最低有效剂量 按需服用</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">长期</td></tr></tbody></table><h3>生活方式调整</h3><ul><li>床头抬高15-20cm（非垫高枕头，需整个床头抬高）</li><li>睡前3小时不进食</li><li>避免：咖啡、浓茶、巧克力、高脂饮食、辛辣刺激</li><li>减重（BMI&lt;25）</li></ul><hr/><p><br></p><h2>二、消化性溃疡</h2><h3>胃溃疡与十二指肠溃疡鉴别</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">特征</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">胃溃疡(GU)</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">十二指肠溃疡(DU)</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">好发部位</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">胃小弯侧胃角</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">十二指肠球部</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">疼痛节律</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">餐后0.5-1h出现→下次餐前缓解</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">空腹痛→进食缓解→下次餐前再痛</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">癌变风险</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">约1%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">极少</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">胃酸分泌</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">正常或偏低</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">偏高</td></tr></tbody></table><h3>病因</h3><ol><li>幽门螺杆菌(Hp)感染（DU中&gt;90%，GU中70-80%）</li><li>NSAIDs/阿司匹林</li><li>应激、吸烟、饮酒、高盐饮食</li></ol><h3>Hp根除方案（四联疗法，14天）</h3><ul><li>方案A（铋剂四联）：PPI bid + 铋剂220mg bid + 阿莫西林1g bid + 克拉霉素500mg bid</li><li>方案B（伴同疗法）：PPI bid + 阿莫西林1g bid + 克拉霉素500mg bid + 甲硝唑400mg bid/tid</li><li>根除后4周复查C13/C14呼气试验</li></ul><h3>并发症</h3><ul><li><strong>上消化道出血</strong>：最常见，表现为呕血+黑便。内镜下Forrest分级指导止血</li><li><strong>穿孔</strong>：突发剧烈刀割样上腹痛→板状腹→X线见膈下游离气体→急诊手术</li><li><strong>幽门梗阻</strong>：反复呕吐隔夜宿食，振水音阳性</li><li><strong>癌变</strong>：GU术后残胃需定期随访</li></ul><hr/><p><br></p><h2>三、功能性消化不良</h2><h3>诊断（罗马IV标准）</h3><p>病程≥6个月，近3个月满足以下≥1条：</p><ul><li>餐后饱胀不适</li><li>早饱感</li><li>上腹痛或烧灼感</li><li>无器质性病变可解释</li></ul><h3>分型</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">亚型</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">主要症状</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">治疗侧重</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">上腹痛综合征(EPS)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">上腹痛、烧灼感</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">PPI/抗酸药</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">餐后不适综合征(PDS)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">饱胀、早饱</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">促动力药</td></tr></tbody></table><h3>治疗</h3><ul><li>一线：促动力药（莫沙必利/多潘立酮）+ 抑酸药</li><li>二线：三环类抗抑郁药（如阿米替林12.5-25mg qn）</li><li>辅助：益生菌、消化酶制剂、心理行为治疗</li></ul><hr/><p><br></p><h2>四、急性胃肠炎</h2><h3>病原学</h3><ul><li>病毒性（占70-80%）：诺如病毒、轮状病毒</li><li>细菌性：沙门菌、副溶血性弧菌、金黄色葡萄球菌（毒素）、大肠杆菌</li></ul><h3>紧急评估：脱水分度</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">程度</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">体征</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">处理</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">轻度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">口唇干燥、尿量正常</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">口服补液</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">中度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">皮肤弹性↓、眼窝凹陷、尿少</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">ORS+密切观察</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">重度</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">意识改变、无尿、休克</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">紧急静脉补液</td></tr></tbody></table><h3>药物选择</h3><ul><li>止泻：蒙脱石散（吸附毒素，不被吸收）</li><li>益生菌：辅助缩短病程</li><li>抗生素指征：高热+T&gt;38.5℃+脓血便+粪便镜检WBC&gt;15/HP</li><li>止吐：甲氧氯普胺10mg im（成人）</li></ul><h3>饮食建议</h3><ul><li>急性期：禁食4-6小时后逐步从流质→半流质→软食过渡</li><li>推荐：白粥、烂面条、蒸蛋羹、香蕉、苹果泥(BRAT饮食)</li><li>避免：牛奶（暂时性乳糖酶缺乏）、高纤维、辛辣、油腻</li></ul><hr/><p><br></p><h2>五、肠易激综合征(IBS)</h2><h3>诊断标准（罗马IV）</h3><p>反复腹痛，近3个月平均每周至少1次，伴以下≥2项：</p><ul><li>与排便相关</li><li>排便频率改变</li><li>粪便性状改变</li></ul><h3>分型</h3><ul><li>IBS-C（便秘型）：硬便/块状便≥25%，稀便/水样便&lt;25%</li><li>IBS-D（腹泻型）：稀便/水样便≥25%，硬便/块状便&lt;25%</li><li>IBS-M（混合型）：两者均≥25%</li><li>IBS-U（不定型）</li></ul><h3>治疗策略</h3><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">分型</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">药物</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">IBS-C</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">利那洛肽、鲁比前列酮、聚乙二醇</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">IBS-D</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">利福昔明（2周）、洛哌丁胺（按需）、5-HT3拮抗剂</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">腹痛</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">匹维溴铵、曲美布汀</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">辅助</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">低FODMAP饮食、益生菌、肠道菌群移植</td></tr></tbody></table><p><br></p>',4,'https://picsum.photos/seed/health4/400/250',NULL,NULL,NULL,'2026-06-01 20:53:31'),(28,'2型糖尿病营养干预方案','<p>一、血糖控制目标</p><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">指标</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">理想</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">一般</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">差</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">空腹血糖(mmol/L)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">4.4-6.1</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">6.2-7.0</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&gt;7.0</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">餐后2h血糖(mmol/L)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">4.4-8.0</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">8.1-10.0</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&gt;10.0</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">HbA1c(%)</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&lt;6.5</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">6.5-7.5</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">&gt;7.5</td></tr></tbody></table><h2>二、每日总热量计算</h2><ul><li>休息状态：25-30 kcal/kg</li><li>轻体力活动：30-35 kcal/kg</li><li>中体力活动：35-40 kcal/kg</li><li>重体力活动：&gt;40 kcal/kg</li></ul><h2>三、三大营养素配比</h2><table style=\"width: auto;\"><tbody><tr><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">营养素</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">供能占比</th><th colSpan=\"1\" rowSpan=\"1\" width=\"auto\">说明</th></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">碳水化合物</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">45%-60%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">优先选择低GI食物</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">蛋白质</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">15%-20%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">肾功能正常者1.0-1.5g/kg/d</td></tr><tr><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">脂肪</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">20%-35%</td><td colSpan=\"1\" rowSpan=\"1\" width=\"auto\">饱和脂肪&lt;7%，反式脂肪&lt;1%</td></tr></tbody></table><h2>四、食物选择红绿灯</h2><h3>绿灯区（推荐）</h3><ul><li>全谷物：燕麦、荞麦、糙米、藜麦</li><li>蔬菜：菠菜、西兰花、黄瓜、番茄、芹菜</li><li>优质蛋白：鱼肉、去皮禽肉、豆腐、蛋清</li></ul><h3>黄灯区（适量）</h3><ul><li>水果：苹果、柚子、草莓、蓝莓（每日&lt;200g）</li><li>根茎类：红薯、土豆、山药（替代主食）</li></ul><h3>红灯区（避免）</h3><ul><li>含糖饮料、果汁、甜点、蜜饯</li><li>精制主食：白米饭、白馒头、白面包（可少量搭配杂粮）</li><li>高GI水果：西瓜、荔枝、龙眼</li></ul><h2>五、运动处方</h2><ul><li>有氧运动：每周5次，每次30分钟，心率=(220-年龄)×60%-70%</li><li>抗阻训练：每周2-3次，每次8-10个动作，每组10-15次</li><li>运动禁忌：血糖&gt;16.7mmol/L时禁止运动</li></ul><h2>六、低血糖处理</h2><p>出现心慌、出汗、手抖、饥饿感时立即测血糖：</p><ul><li>血糖&lt;3.9mmol/L：口服15g葡萄糖或150ml果汁，15分钟后复测</li><li>意识不清：立即拨打120，不可强行喂食</li></ul><p><br></p>',1,'https://picsum.photos/seed/health2/400/250',NULL,NULL,NULL,'2026-06-01 20:54:15'),(29,'糖尿病患者的医学营养治疗与日常饮食指南','<ol><li>糖尿病与医学营养治疗 (MNT) 简介</li></ol><p>糖尿病（Diabetes Mellitus）是一种以高血糖为特征的代谢性疾病。医学营养治疗（Medical Nutrition Therapy, MNT）是糖尿病综合管理的基础，旨在通过合理的饮食调整，帮助患者控制血糖、血脂和血压，预防或延缓糖尿病并发症的发生。</p><h2>2. 核心饮食原则</h2><h3>2.1 碳水化合物的管理</h3><p>碳水化合物是影响餐后血糖的最主要因素。糖尿病患者不需要完全戒除碳水，而是需要“聪明地”选择。</p><ul><li>血糖生成指数 (GI)：建议多选择低GI（&lt;55）的食物，如燕麦、糙米、杂豆、全麦面包。这些食物消化吸收慢，血糖升高平缓。</li><li>控制总摄入量：使用“食物交换份”或碳水化合物计数法，保持每餐碳水化合物的摄入量相对稳定。</li><li>避免添加糖：尽量避免含糖饮料、果汁、甜点和精加工零食。</li></ul><h3>2.2 优质蛋白质的摄入</h3><ul><li>蛋白质不会引起血糖的剧烈波动，且能增加饱腹感。</li><li>建议选择瘦肉、去皮家禽、鱼类、蛋类以及豆制品。</li><li>对于已出现糖尿病肾病（DKD）的患者，需在医生指导下限制蛋白质的摄入量，以减轻肾脏负担。</li></ul><h3>2.3 脂肪的选择</h3><ul><li>限制饱和脂肪的摄入（如肥肉、黄油、猪油），占总热量的比例应低于 7%。</li><li>严禁反式脂肪（如人造奶油、部分氢化植物油）。</li><li>增加单不饱和脂肪和多不饱和脂肪的比例（如橄榄油、牛油果、深海鱼、坚果）。</li></ul><h2>3. 推荐的饮食模式</h2><ul><li>地中海饮食：以植物性食物为主，富含橄榄油和鱼类，被证明对改善胰岛素抵抗和心血管健康非常有效。</li><li>DASH饮食（终止高血压膳食疗法）：强调全谷物、蔬菜、水果和低脂奶制品，适合伴有高血压的糖尿病患者。</li></ul><h2>4. 常见误区与问答 (Q&A)</h2><ul><li>Q：糖尿病患者可以吃水果吗？ A：可以。但应在血糖控制相对稳定时食用，选择低GI的水果（如苹果、柚子、草莓、樱桃），并放在两餐之间作为加餐，而不是饭后立即食用。每次食用量应控制在拳头大小（约200克）。</li><li>Q：无糖食品就可以随便吃吗？ A：不可以。所谓的“无糖食品”通常只是不含蔗糖，但仍然可能含有碳水化合物（如面粉、淀粉）或脂肪，过量食用依然会导致血糖升高和热量超标。</li><li>Q：主食吃得越少，对控制血糖越好吗？ A：错误。过度限制主食可能导致能量不足，引发低血糖。长期碳水摄入不足还可能导致体内脂肪过度分解，产生酮体，甚至诱发酮症酸中毒。关键在于“控制总量，优化结构”。</li></ul>',1,'https://picsum.photos/seed/health5/400/250',NULL,NULL,NULL,'2026-06-01 20:54:45');
